1	package server
2	
3	import (
4		"bytes"
5		"errors"
6		"net/http"
7	
8		"github.com/alicegogogogogo/local-first-sync-service/internal/store"
9	)
10	
11	// handleCRDTStateSubscribe is the WebSocket subscription to a document's
12	// merged CRDT state, mounted under the session view:
13	//
14	//	GET /v1/sessions/{sessionId}/documents/{documentId}/crdt/state/subscribe
15	//
16	// The subscription identity is entirely the existing session: the session's
17	// owning device is the only credential and no new auth is introduced. The
18	// validation order is fixed and entirely pre-upgrade, writing nothing:
19	//
20	//  1. the request must be a GET carrying a valid WebSocket upgrade handshake
21	//     (400 JSON otherwise; a malformed path is a 400 JSON too),
22	//  2. the session must currently exist (404 JSON),
23	//  3. its device must currently hold permission for the document (403 JSON).
24	//
25	// After the upgrade the server first pushes the current merged state; a
26	// document without any CRDT operation yet sends nothing and waits silently
27	// until its first state appears. From then on every commit that actually
28	// changes the merge — a counter's per-device maximum advancing, the set union
29	// growing — is pushed as one text frame in transaction-commit order.
30	// Idempotent repeats, rejected regressions and wholly invalid batches change
31	// no state and produce no frame; re-adding an existing set element pushes
32	// nothing either.
33	//
34	// Each message is one text frame whose payload is byte-for-byte the state
35	// read endpoint's body: compact single-line JSON with the keys in type, value
36	// order, terminated by a newline. The connection is push-only: inbound data
37	// frames are read and discarded, ping is answered with pong. A permission
38	// revoke after the upgrade ends the subscription with close code 4403 —
39	// stickily, a re-grant never revives this connection — and a termination
40	// signal ends every subscription with 1001. Subscriptions are not persisted;
41	// after a restart a fresh subscription immediately receives the consistent
42	// current merged state.
43	func handleCRDTStateSubscribe(s *store.Store, w http.ResponseWriter, r *http.Request) {
44		sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
45		documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty
46	
47		if !checkWebSocketUpgrade(r) {
48			writeError(w, http.StatusBadRequest, "a WebSocket upgrade handshake is required")
49			return
50		}
51	
52		deviceID, err := s.SessionDevice(sessionID)
53		if err != nil {
54			if errors.Is(err, store.ErrSessionNotFound) {
55				writeError(w, http.StatusNotFound, "session not found")
56				return
57			}
58			writeError(w, http.StatusInternalServerError, "failed to look up session")
59			return
60		}
61		authorized, err := s.DocumentAuthorized(documentID, deviceID)
62		if err != nil {
63			writeError(w, http.StatusInternalServerError, "failed to look up permission")
64			return
65		}
66		if !authorized {
67			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
68			return
69		}
70	
71		conn, err := upgradeWebSocket(w, r)
72		if err != nil {
73			// The 101 could not be written and the connection has been hijacked
74			// (or is gone); no JSON error can be produced and nothing was
75			// registered.
76			return
77		}
78	
79		serveCRDTStateSubscription(r, s, conn, documentID, deviceID)
80	}
81	
82	// serveCRDTStateSubscription runs one upgraded CRDT-state connection to
83	// completion. Registration and the initial state read are one atomic step in
84	// the store, so a state-changing commit lands either inside that initial
85	// state or in the subscription's queue: the first frame is the current merge
86	// and every later frame is strictly newer, in commit order. The method
87	// returns when the client leaves, permission is revoked or the store starts
88	// closing; the hijacked connection is closed on exit.
89	func serveCRDTStateSubscription(r *http.Request, s *store.Store, conn *wsConn, documentID, deviceID string) {
90		initial, sub, unregister, err := s.OpenCRDTSubscription(documentID, deviceID)
91		if err != nil {
92			_ = conn.Close(wsCloseInternalError, "internal error")
93			_ = conn.NetClose()
94			return
95		}
96		defer func() {
97			unregister()
98			_ = conn.NetClose()
99		}()
100	
101		clientGone := make(chan struct{})
102		go func() {
103			defer close(clientGone)
104			for {
105				if _, _, readErr := conn.ReadMessage(); readErr != nil {
106					// A malformed frame ends with the RFC protocol-error code; a
107					// client close is already echoed inside ReadMessage; a network
108					// drop needs no frame.
109					var protoErr *wsProtocolErrorString
110					if errors.As(readErr, &protoErr) {
111						_ = conn.Close(wsCloseProtocolError, "protocol error")
112					}
113					return
114				}
115				// Push-only channel: an inbound data frame is read and discarded;
116				// the client cannot submit or mutate any operation over it.
117			}
118		}()
119	
120		// endNow maps a closing store to 1001 and a sticky revoke to 4403, waiting
121		// briefly for the peer's close echo. Termination takes precedence over a
122		// racing revoke. It returns true when the subscription must end.
123		endNow := func() bool {
124			if s.Closing() {
125				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
126				return true
127			}
128			select {
129			case <-sub.Revoked():
130				endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
131				return true
132			default:
133			}
134			return false
135		}
136	
137		// closingOnly honors a termination signal before the first frame; a revoke
138		// racing the initial push is left for the main loop so the state that was
139		// authorized at handshake still reaches the client ahead of the 4403.
140		closingOnly := func() bool {
141			if s.Closing() {
142				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
143				return true
144			}
145			return false
146		}
147	
148		// lastSent skips any queued frame that encodes the same state the
149		// connection already sent. Registration-vs-commit atomicity already makes
150		// this unnecessary (a queued state is always strictly newer), so this is
151		// only a belt-and-braces guard for the register/read boundary.
152		var lastSent []byte
153		send := func(state store.CRDTState) bool {
154			frame := encodeCRDTStateFrame(state)
155			if bytes.Equal(frame, lastSent) {
156				return true
157			}
158			if writeErr := conn.WriteText(frame); writeErr != nil {
159				return false
160			}
161			lastSent = frame
162			return true
163		}
164	
165		// First push: the current merged state. A document with no operation yet
166		// stays silent until its first state arrives. A termination signal that
167		// raced the registration is honored before anything is sent.
168		if closingOnly() {
169			return
170		}
171		if initial != nil {
172			if !send(*initial) {
173				return
174			}
175		}
176	
177		for {
178			if endNow() {
179				return
180			}
181	
182			// Drain every committed state queued since the last park, in commit
183			// order; a revoke or termination is honored between frames.
184			for _, state := range sub.Drain() {
185				if endNow() {
186					return
187				}
188				if !send(state) {
189					return
190				}
191			}
192			if endNow() {
193				return
194			}
195	
196			select {
197			case <-sub.Wake():
198				// A coalescing "drain now" signal; loop and flush the whole queue.
199			case <-sub.Revoked():
200				if s.Closing() {
201					endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
202					return
203				}
204				endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
205				return
206			case <-clientGone:
207				return
208			case <-r.Context().Done():
