1	package store
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"path/filepath"
8		"sync"
9		"testing"
10	)
11	
12	func rawInt(n int64) json.RawMessage {
13		return json.RawMessage(fmt.Sprintf("%d", n))
14	}
15	
16	func registerDevices(t *testing.T, s *Store, devices ...string) {
17		t.Helper()
18		for _, d := range devices {
19			if _, err := s.RegisterDevice(d); err != nil {
20				t.Fatalf("register %s: %v", d, err)
21			}
22		}
23	}
24	
25	func counterOps(device string, vals ...int64) []CRDTOp {
26		ops := make([]CRDTOp, len(vals))
27		for i, v := range vals {
28			ops[i] = CRDTOp{ID: fmt.Sprintf("%s-op-%d", device, i+1), DeviceID: device, Value: rawInt(v)}
29		}
30		return ops
31	}
32	
33	func TestCRDTNotFoundBeforeAnyOp(t *testing.T) {
34		s, _ := Open("")
35		defer func() { _ = s.Close() }()
36	
37		if _, err := s.GetCRDTState("doc"); !errors.Is(err, ErrCRDTNotFound) {
38			t.Fatalf("empty state err = %v, want ErrCRDTNotFound", err)
39		}
40	}
41	
42	func TestCRDTCounterMergeIsSumOfPerDeviceMaxima(t *testing.T) {
43		s, _ := Open("")
44		defer func() { _ = s.Close() }()
45		registerDevices(t, s, "dev-1", "dev-2", "dev-3")
46	
47		submit := func(device string, val int64, id string) {
48			t.Helper()
49			results, err := s.SubmitCRDTOps("doc", CRDTTypeCounter, []CRDTOp{
50				{ID: id, DeviceID: device, Value: rawInt(val)},
51			})
52			if err != nil {
53				t.Fatalf("submit %s=%d: %v", device, val, err)
54			}
55			if !results[0].Created {
56				t.Fatalf("%s=%d should be created", device, val)
57			}
58		}
59	
60		// Interleave devices out of order; the merge depends only on each max.
61		submit("dev-1", 5, "a1")
62		submit("dev-2", 2, "b1")
63		submit("dev-1", 9, "a2") // dev-1 max advances 5 -> 9
64		submit("dev-3", 0, "c1") // zero still establishes the device
65		submit("dev-1", 9, "a3") // equal maximum: accepted, created (new id), state unchanged
66	
67		state, err := s.GetCRDTState("doc")
68		if err != nil {
69			t.Fatal(err)
70		}
71		if state.Type != CRDTTypeCounter {
72			t.Fatalf("type = %q", state.Type)
73		}
74		if string(state.Value) != "11" { // 9 + 2 + 0
75			t.Fatalf("merged value = %s, want 11", state.Value)
76		}
77	}
78	
79	func TestCRDTCounterRejectsRegression(t *testing.T) {
80		s, _ := Open("")
81		defer func() { _ = s.Close() }()
82		registerDevices(t, s, "dev-1", "dev-2")
83	
84		if _, err := s.SubmitCRDTOps("doc", CRDTTypeCounter, counterOps("dev-1", 5)); err != nil {
85			t.Fatal(err)
86		}
87		// A regression is a 409 conflict and leaves the state untouched.
88		_, err := s.SubmitCRDTOps("doc", CRDTTypeCounter, []CRDTOp{
89			{ID: "dev-1-op-regress", DeviceID: "dev-1", Value: rawInt(4)},
90		})
91		var conflict *ErrCRDTConflict
92		if !errors.As(err, &conflict) {
93			t.Fatalf("regression err = %v, want *ErrCRDTConflict", err)
94		}
95		state, _ := s.GetCRDTState("doc")
96		if string(state.Value) != "5" {
97			t.Fatalf("state after regression = %s, want 5", state.Value)
98		}
99	
100		// Another device advancing must not be blocked by the rejected batch.
101		if _, err := s.SubmitCRDTOps("doc", CRDTTypeCounter, counterOps("dev-2", 7)); err != nil {
102			t.Fatal(err)
103		}
104		state, _ = s.GetCRDTState("doc")
105		if string(state.Value) != "12" {
106			t.Fatalf("state = %s, want 12", state.Value)
107		}
108	}
109	
110	func TestCRDTTypeIsFixedOnFirstBatch(t *testing.T) {
111		s, _ := Open("")
112		defer func() { _ = s.Close() }()
113		registerDevices(t, s, "dev-1", "dev-2")
114	
115		if _, err := s.SubmitCRDTOps("doc", CRDTTypeCounter, counterOps("dev-1", 1)); err != nil {
116			t.Fatal(err)
117		}
118		// Declaring the other type later is a conflict, even from another device.
119		_, err := s.SubmitCRDTOps("doc", CRDTTypeGSet, []CRDTOp{
120			{ID: "g1", DeviceID: "dev-2", Elements: []string{"x"}},
121		})
122		var conflict *ErrCRDTConflict
123		if !errors.As(err, &conflict) {
124			t.Fatalf("type change err = %v, want *ErrCRDTConflict", err)
125		}
126		if conflict.ID != "" {
127			t.Fatalf("document-level conflict should carry no op id, got %q", conflict.ID)
128		}
129		// Re-declaring the fixed type still works.
130		if _, err := s.SubmitCRDTOps("doc", CRDTTypeCounter, counterOps("dev-2", 3)); err != nil {
131			t.Fatalf("same-type submit: %v", err)
132		}
133		state, _ := s.GetCRDTState("doc")
134		if state.Type != CRDTTypeCounter || string(state.Value) != "4" {
135			t.Fatalf("state = %s %s", state.Type, state.Value)
136		}
137	}
138	
139	func TestCRDTConcurrentTypeDeclarationExactlyOneWins(t *testing.T) {
140		s, _ := Open("")
141		defer func() { _ = s.Close() }()
142		registerDevices(t, s, "dev-1", "dev-2")
143	
144		const n = 40
145		var wg sync.WaitGroup
146		wins := make(chan string, 2*n)
147		start := make(chan struct{})
148		for i := 0; i < n; i++ {
149			wg.Add(2)
150			go func(i int) {
151				defer wg.Done()
152				<-start
153				_, err := s.SubmitCRDTOps("race", CRDTTypeCounter, []CRDTOp{
154					{ID: fmt.Sprintf("c-%d", i), DeviceID: "dev-1", Value: rawInt(int64(i + 1))},
155				})
156				if err == nil {
157					wins <- "counter"
158				}
159			}(i)
160			go func(i int) {
161				defer wg.Done()
162				<-start
163				_, err := s.SubmitCRDTOps("race", CRDTTypeGSet, []CRDTOp{
164					{ID: fmt.Sprintf("g-%d", i), DeviceID: "dev-2", Elements: []string{fmt.Sprintf("e%d", i)}},
165				})
166				if err == nil {
167					wins <- "gset"
168				}
169			}(i)
170		}
171		close(start)
172		wg.Wait()
173		close(wins)
174	
175		counts := map[string]int{}
176		for w := range wins {
177			counts[w]++
178		}
179		// Exactly one type's first batch lands; every same-type batch that arrives
180		// after it also succeeds, so one counter is exactly 1 (or one gset >= 1).
181		if counts["counter"] > 0 && counts["gset"] > 0 {
182			t.Fatalf("both types accepted: %v", counts)
183		}
184		if counts["counter"] == 0 && counts["gset"] == 0 {
185			t.Fatal("neither type won the race")
186		}
187		// The losing type must have exactly zero accepted batches.
188		state, err := s.GetCRDTState("race")
189		if err != nil {
190			t.Fatal(err)
191		}
192		if counts["counter"] > 0 && state.Type != CRDTTypeCounter {
193			t.Fatalf("counter won but state type = %q", state.Type)
194		}
195		if counts["gset"] > 0 && state.Type != CRDTTypeGSet {
196			t.Fatalf("gset won but state type = %q", state.Type)
197		}
198	}
199	
200	func TestCRDTGSetUnionSortedAndIdempotent(t *testing.T) {
201		s, _ := Open("")
202		defer func() { _ = s.Close() }()
203		registerDevices(t, s, "dev-1", "dev-2")
204	
205		submit := func(device, id string, elements ...string) []CRDTResult {
206			t.Helper()
207			results, err := s.SubmitCRDTOps("doc", CRDTTypeGSet, []CRDTOp{
208				{ID: id, DeviceID: device, Elements: elements},
209			})
210			if err != nil {
211				t.Fatalf("submit %s: %v", id, err)
212			}
213			return results
214		}
215	
216		submit("dev-1", "g1", "banana", "apple")
217		submit("dev-2", "g2", "cherry", "apple") // apple is a duplicate element
218		// Re-adding existing elements with a new id is accepted but changes nothing.
219		r := submit("dev-1", "g3", "apple", "banana", "cherry")
220		if !r[0].Created {
221			t.Fatal("a new op id adding only existing elements is still created")
222		}
223	
224		state, err := s.GetCRDTState("doc")
225		if err != nil {
226			t.Fatal(err)
227		}
228		if state.Type != CRDTTypeGSet {
229			t.Fatalf("type = %q", state.Type)
230		}
231		var got []string
232		if err := json.Unmarshal(state.Value, &got); err != nil {
233			t.Fatal(err)
234		}
235		want := []string{"apple", "banana", "cherry"}
236		if len(got) != len(want) {
237			t.Fatalf("elements = %v, want %v", got, want)
238		}
239		for i := range want {
240			if got[i] != want[i] {
241				t.Fatalf("elements = %v, want sorted %v", got, want)
242			}
243		}
244	}
245	
246	func TestCRDTGSetEmptyStateIsEmptyArray(t *testing.T) {
247		s, _ := Open("")
248		defer func() { _ = s.Close() }()
249		registerDevices(t, s, "dev-1")
250	
251		// A first batch always adds at least one element at the API boundary; at
252		// the store layer the document exists once a batch lands, and the union is
253		// presented as [] rather than null when nothing remains.
254		if _, err := s.SubmitCRDTOps("doc", CRDTTypeGSet, []CRDTOp{
255			{ID: "g1", DeviceID: "dev-1", Elements: []string{"only"}},
256		}); err != nil {
257			t.Fatal(err)
258		}
259		state, _ := s.GetCRDTState("doc")
260		var got []string
261		if err := json.Unmarshal(state.Value, &got); err != nil || len(got) != 1 || got[0] != "only" {
262			t.Fatalf("state = %s", state.Value)
263		}
264	}
