package server

import (
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

func crdtCounterBody(device string, ops ...map[string]any) map[string]any {
	return map[string]any{"deviceId": device, "type": "counter", "ops": ops}
}

